import torch; exec("class Solution:\n    def get_dataset(self, positive, negative):\n        all_words = set()\n        for s in positive + negative:\n            for w in s.split():\n                all_words.add(w)\n        sorted_words = sorted(all_words)\n        word_to_idx = {w: i+1 for i, w in enumerate(sorted_words)}\n        def encode(s):\n            return [word_to_idx[w] for w in s.split()]\n        pos_enc = [encode(s) for s in positive]\n        neg_enc = [encode(s) for s in negative]\n        all_enc = pos_enc + neg_enc\n        max_len = max(len(e) for e in all_enc)\n        padded = [e + [0] * (max_len - len(e)) for e in all_enc]\n        return torch.tensor(padded)")